// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List non-secret configuration readiness
	// (GET /api/v1/admin/config/overview)
	GetAdminConfigOverview(w http.ResponseWriter, r *http.Request)
	// Invalidate the current admin session
	// (POST /api/v1/auth/logout)
	LogoutAdmin(w http.ResponseWriter, r *http.Request, params LogoutAdminParams)
	// Return the authenticated admin principal
	// (GET /api/v1/auth/session)
	GetAuthSession(w http.ResponseWriter, r *http.Request)
	// List customers using a keyset cursor
	// (GET /api/v1/customers)
	ListCustomers(w http.ResponseWriter, r *http.Request, params ListCustomersParams)
	// Get a channel-neutral customer by OneID
	// (GET /api/v1/customers/{customer_id})
	GetCustomer(w http.ResponseWriter, r *http.Request, customerId CustomerID)
	// Update customer-owned profile fields
	// (PATCH /api/v1/customers/{customer_id})
	UpdateCustomer(w http.ResponseWriter, r *http.Request, customerId CustomerID, params UpdateCustomerParams)
	// List append-only customer events using a keyset cursor
	// (GET /api/v1/customers/{customer_id}/events)
	ListCustomerEvents(w http.ResponseWriter, r *http.Request, customerId CustomerID, params ListCustomerEventsParams)
	// Set or clear a customer's stage
	// (PUT /api/v1/customers/{customer_id}/stage)
	SetCustomerStage(w http.ResponseWriter, r *http.Request, customerId CustomerID, params SetCustomerStageParams)
	// Idempotently remove one local tag from a customer
	// (DELETE /api/v1/customers/{customer_id}/tags/{tag_id})
	RemoveCustomerTag(w http.ResponseWriter, r *http.Request, customerId CustomerID, tagId TagID, params RemoveCustomerTagParams)
	// Idempotently apply one local tag to a customer
	// (PUT /api/v1/customers/{customer_id}/tags/{tag_id})
	AddCustomerTag(w http.ResponseWriter, r *http.Request, customerId CustomerID, tagId TagID, params AddCustomerTagParams)
	// Bind a scoped identity to a channel-neutral customer
	// (POST /api/v1/identity/bind)
	BindIdentity(w http.ResponseWriter, r *http.Request, params BindIdentityParams)
	// Attribute or persist an external event without guessing identity
	// (POST /api/v1/identity/ingest)
	IngestIdentityEvent(w http.ResponseWriter, r *http.Request, params IngestIdentityEventParams)
	// List pending identity merge reviews without exposing raw identities
	// (GET /api/v1/identity/merge-reviews)
	ListIdentityMergeReviews(w http.ResponseWriter, r *http.Request, params ListIdentityMergeReviewsParams)
	// Approve one versioned merge review with an explicit primary customer
	// (POST /api/v1/identity/merge-reviews/{review_id}/approve)
	ApproveIdentityMergeReview(w http.ResponseWriter, r *http.Request, reviewId MergeReviewID, params ApproveIdentityMergeReviewParams)
	// Reject one versioned merge review without changing bindings
	// (POST /api/v1/identity/merge-reviews/{review_id}/reject)
	RejectIdentityMergeReview(w http.ResponseWriter, r *http.Request, reviewId MergeReviewID, params RejectIdentityMergeReviewParams)
	// Resolve one scoped identity without implicit creation
	// (POST /api/v1/identity/resolve)
	ResolveIdentity(w http.ResponseWriter, r *http.Request)
	// List global customer stages in deterministic order
	// (GET /api/v1/stages)
	ListStages(w http.ResponseWriter, r *http.Request)
	// Create one global customer stage
	// (POST /api/v1/stages)
	CreateStage(w http.ResponseWriter, r *http.Request, params CreateStageParams)
	// Rename one global customer stage
	// (PATCH /api/v1/stages/{stage_id})
	RenameStage(w http.ResponseWriter, r *http.Request, stageId StageID, params RenameStageParams)
	// List the local tag catalog in deterministic order
	// (GET /api/v1/tags)
	ListTags(w http.ResponseWriter, r *http.Request)
}

